        out = []
        for k, col in cells.items():
            t = tgt.get(k)
            if t is not None and t != col:
                ri, ci = (int(x) for x in k.split(','))
                out.append({'key': k, 'row': row_axis[ri], 'col': col_axis[ci],
                            'cur': col, 'want': t})
        return out

