    """Exact per-pixel observation of the frame: every visible coordinate once.

    Returns {"runs": [[row, first_col, last_col_inclusive, color], ...]}.
    """
    rows = frame.ascii.split('\n')
    runs = []
    for r, line in enumerate(rows):
